// Materialise one task per (commitment, period) for this month and the next.
//
// APPEND-ONLY, and that is the whole point of the diff below. An upsert keyed on
// task_id would look equivalent and would reset status/assignee/closed_at to
// 'open' every single morning — silently undoing yesterday's taps and every
// agent result. Existing task_ids are skipped, never rewritten.
//
// Emitting zero items is the normal quiet-day outcome: n8n simply does not run
// the append node, so no If node is needed to guard it.

const commitments = $('Get Commitments').all().map((i) => i.json);
const existing = new Set(
  $('Get Existing Tasks').all().map((i) => String(i.json.task_id || '')).filter(Boolean),
);

const pad = (n) => String(n).padStart(2, '0');
const daysInMonth = (y, m) => new Date(y, m + 1, 0).getDate();

// 'eom' rather than 31, because a literal 31 does not exist in February.
const dayOf = (v, y, m) => {
  const s = String(v ?? '').trim().toLowerCase();
  if (!s) return null;
  if (s === 'eom') return daysInMonth(y, m);
  const n = parseInt(s, 10);
  return Number.isFinite(n) ? Math.min(n, daysInMonth(y, m)) : null;
};

const now = new Date();
const y = now.getFullYear();
const m = now.getMonth();
const periods = [
  { y, m },
  { y: m === 11 ? y + 1 : y, m: (m + 1) % 12 },
];

const out = [];

for (const c of commitments) {
  if (!c.commitment_id) continue;
  if (String(c.status || '').trim().toLowerCase() !== 'active') continue;
  // A row with valid_to set is a superseded version kept for history.
  if (String(c.valid_to || '').trim()) continue;
  // v1 handles monthly only. Quarterly and yearly are skipped rather than shown
  // with a guessed date — their next occurrence has to be anchored to valid_from.
  if (String(c.cadence || '').trim().toLowerCase() !== 'monthly') continue;

  const from = Date.parse(c.valid_from);

  for (const p of periods) {
    const period = `${p.y}-${pad(p.m + 1)}`;
    const task_id = `${c.commitment_id}@${period}`;
    if (existing.has(task_id)) continue;

    const dd = dayOf(c.due_day || c.charge_day, p.y, p.m);
    if (dd === null) continue;

    const due = new Date(p.y, p.m, dd);

    // The invoice date, which is a different day from the deadline and is the one
    // the reconciler hunts for in Billing_Ledger.
    const cd = dayOf(c.charge_day || c.due_day, p.y, p.m);
    const charge = cd === null ? due : new Date(p.y, p.m, cd);

    // No backfill, gated on the CHARGE date rather than the deadline. An
    // obligation is created when the invoice is issued, not when it falls due.
    // Gating on the deadline pulls in the period whose invoice was issued — and
    // quite possibly already paid — before this ledger existed, and then nags
    // about it for three weeks.
    if (Number.isFinite(from) && charge.getTime() < from) continue;

    out.push({
      json: {
        task_id,
        commitment_id: c.commitment_id,
        vendor: c.vendor || '',
        period,
        charge_date: `${p.y}-${pad(p.m + 1)}-${pad(cd ?? dd)}`,
        due_date: `${p.y}-${pad(p.m + 1)}-${pad(dd)}`,
        amount: c.amount_expected ?? '',
        currency: c.currency || '',
        // Denormalised so the digest reads one tab, and so the row records the
        // terms as they stood when the task was created.
        payment_method: String(c.payment_method || '').trim().toLowerCase(),
        action: 'pay',
        status: 'open',
        assignee: '',
        assigned_at: '',
        closed_at: '',
        evidence: '',
        attempts: 0,
        notes: '',
      },
    });
  }
}

return out;

// Return an empty object on purpose.
//
// menu-handler's 'Format Skill Response' forwards a reply only when the
// subworkflow returns a 'response' field, and shows "temporarily unavailable"
// when it sees an 'error'. Both Telegram nodes above are continueOnFail, so
// without this node a failed redraw would emit an error payload and tell the
// user the tap failed — after the row was already written. The write is what
// matters; the redraw is cosmetic.
return [{ json: {} }];

// Briefing plugin. Returns ONE item shaped by the contract in
// 05_daily-briefing/docs/briefing-plugin-spec.md.
//
// PLAIN TEXT ONLY — never HTML. The briefing escapes centrally. Emitting markup
// here would make escaping every plugin's shared responsibility, and one missed
// escape anywhere kills the whole sendMessage.

const MANUAL = ['qr-invoice', 'bank-transfer', 'twint'];
const MAX_BUTTONS = 5;
// Telegram caps callback_data at 64 bytes and rejects the ENTIRE keyboard if one
// button is over — so an oversized id costs every button, not just its own.
const CB_LIMIT = 60;
const DAY = 86400000;

const input = $('Called').first().json;
const parsed = Date.parse(`${String(input.date || '').slice(0, 10)}T00:00:00`);
const base = Number.isFinite(parsed) ? new Date(parsed) : new Date();
const startOfDay = new Date(base.getFullYear(), base.getMonth(), base.getDate()).getTime();

const rows = $('Get Tasks').all().map((i) => i.json).filter((t) => t && t.task_id);

const closed = ['done', 'cancelled'];
const live = rows.filter((t) => !closed.includes(String(t.status || '').trim().toLowerCase()));

// One line per commitment: the nearest outstanding period. The generator keeps
// two months of tasks alive, but showing both would double the list every day —
// next month surfaces only once this month is closed.
const byCommitment = new Map();
for (const t of live) {
  const key = String(t.commitment_id || t.task_id);
  const prev = byCommitment.get(key);
  if (!prev || String(t.due_date) < String(prev.due_date)) byCommitment.set(key, t);
}

const shown = [...byCommitment.values()]
  .sort((a, b) => String(a.due_date).localeCompare(String(b.due_date)));

const toPay = [];
const leaving = [];
const actions = [];
let total = 0;
let currency = '';

for (const t of shown) {
  const amt = parseFloat(String(t.amount ?? '').replace(',', '.'));
  if (Number.isFinite(amt)) {
    total += amt;
    currency = currency || String(t.currency || '');
  }

  const dueTs = Date.parse(`${String(t.due_date || '')}T00:00:00`);
  const d = Number.isFinite(dueTs) ? Math.round((dueTs - startOfDay) / DAY) : null;
  const when = d === null ? 'no due date'
    : d < 0 ? `⚠️ ${-d}d overdue`
      : d === 0 ? '⚠️ due today'
        : `due in ${d}d`;

  const money = Number.isFinite(amt)
    ? `${t.currency || ''} ${amt.toFixed(2)}`.trim()
    : 'amount unknown';

  const status = String(t.status || '').trim().toLowerCase();
  // 'failed' stays on the list and says so. Presence is the default state, so a
  // task nobody finished needs no error handling to remain visible.
  const state = status === 'assigned' ? ' · ⏳ assigned'
    : status === 'failed' ? ' · ⚠️ failed'
      : '';

  // Audit findings ride on notes and are shown for ANY status — a reopened task
  // is 'open' again, so gating this on 'failed' would hide the reason it came back.
  const flag = String(t.notes || '').trim();
  const who = t.vendor || t.commitment_id;
  const line = `${who} · ${money} · ${when}${state}${flag ? ` · ⚠️ ${flag}` : ''}`;

  if (MANUAL.includes(String(t.payment_method || '').trim().toLowerCase())) {
    toPay.push(line);

    // Only money that leaves if we act gets a button. A checkbox next to a direct
    // debit invites ticking something you did not do.
    // Two verbs, because they are genuinely different claims: 'done' is a
    // self-report that the money moved, 'assign' hands the task to an agent and
    // leaves it open. Collapsing them would make an assignment look like payment.
    const cbAssign = `tk|a|${t.task_id}`;
    if (actions.length < MAX_BUTTONS && cbAssign.length <= CB_LIMIT && status === 'open') {
      actions.push({
        text: `${who} · ${money} · ${when}`,
        buttons: [
          { label: '✅ Done', cb: `tk|d|${t.task_id}` },
          { label: '🤖 Assign', cb: cbAssign },
        ],
      });
    }
  } else {
    leaving.push(line);
  }
}

const blocks = [];
if (shown.length) {
  blocks.push({
    items: [`${currency} ${total.toFixed(2)}/mo · ${shown.length} commitment${shown.length === 1 ? '' : 's'}`],
  });
}
if (toPay.length) blocks.push({ heading: 'To pay', items: toPay });
if (leaving.length) blocks.push({ heading: 'Leaving', items: leaving });

return [{
  json: {
    key: 'commitments',
    icon: '💳',
    title: 'COMMITMENTS',
    blocks,
    actions,
    empty: 'Nothing tracked yet',
  },
}];

// Stage 4 audit. Runs daily straight after the generator and writes what it finds
// as STATE on Tasks rows — so the morning briefing renders it without ever having
// to read the ledger itself.
//
// What this can and cannot prove, because the difference matters:
// Billing_Ledger holds INVOICES. It can confirm that a bill existed and what it
// said. It cannot confirm that money moved, unless a receipt happens to arrive
// and fill date_paid. So a claimed-done WITH a matching invoice is left alone —
// there is no evidence source that would justify second-guessing it. A
// claimed-done with NO invoice at all is reopened, because that claim is about a
// bill that never existed.

const commitments = $('Get Commitments').all().map((i) => i.json).filter((c) => c && c.commitment_id);
const tasks = $('Get Existing Tasks').all().map((i) => i.json).filter((t) => t && t.task_id);
const ledger = $('Get Ledger').all().map((i) => i.json).filter((r) => r && (r.counterparty_name || r.email_id));

// An invoice cannot be missing before it was ever due to exist. The audit only
// judges a period once its charge date has passed AND the ledger has had time to
// receive it — project 04 fills Billing_Ledger from email, which is not instant.
// Without this gate, ticking next month's bill today gets reopened tomorrow for
// the absence of a document nobody has issued yet.
const EVIDENCE_GRACE_DAYS = 7;
const NOW = Date.now();

const byId = new Map(commitments.map((c) => [c.commitment_id, c]));
const norm = (s) => String(s ?? '').toLowerCase().trim();
const num = (v) => parseFloat(String(v ?? '').replace(',', '.'));

// counterparty_name is LLM-extracted from whatever the letterhead said, so it
// arrives as "TalkTalk", "Talk Talk AG" or "talktalk". match_hints exists exactly
// to absorb that; email_id is the more reliable half of the haystack.
const matches = (row, c) => {
  const hints = String(c.match_hints || '').split('|').map(norm).filter(Boolean);
  if (!hints.length) return false;
  const hay = norm(row.counterparty_name) + ' ' + norm(row.email_id);
  return hints.some((h) => hay.includes(h));
};

const out = [];

for (const t of tasks) {
  const c = byId.get(t.commitment_id);
  if (!c) continue;

  const period = String(t.period || '');
  const found = ledger.filter((r) => String(r.invoice_date || '').startsWith(period) && matches(r, c));

  const status = norm(t.status);
  const notes = [];
  let newStatus = t.status;

  const chargeTs = Date.parse(String(t.charge_date || '') + 'T00:00:00');
  // Unparseable charge_date => never reopen. A missing date is a reason to leave
  // the claim alone, not to overturn it.
  const evidenceIsDue = Number.isFinite(chargeTs)
    && NOW > chargeTs + EVIDENCE_GRACE_DAYS * 86400000;

  // OPT-IN, per commitment, and off unless the sheet says otherwise.
  //
  // Reopening is the only thing here that OVERTURNS a human decision rather than
  // annotating it, so it has to be asked for. It is also only meaningful where an
  // absent document actually means something: a vendor that bills but never
  // confirms payment gives the audit nothing to find, and reopening on that
  // silence would just undo a tick every week for no reason.
  const verifyDone = ['yes', 'true', 'on', '1'].includes(norm(c.verify_done));

  if (status === 'done' && found.length === 0 && evidenceIsDue && verifyDone) {
    // Resurrection. Optimistic hide is fine; an unexamined claim is not.
    newStatus = 'open';
    notes.push('reopened: marked done but no invoice found for ' + period);
  }

  if (found.length) {
    const expected = num(t.amount);
    const billed = found.reduce((s, r) => s + (num(r.subtotal_amount) || 0), 0);
    const tol = num(c.tolerance_pct) || 0;
    if (expected > 0 && billed > 0) {
      const drift = Math.abs(billed - expected) / expected * 100;
      if (drift > tol) {
        notes.push('billed ' + billed.toFixed(2) + ' vs expected ' + expected.toFixed(2)
          + ' (' + drift.toFixed(0) + '% over a ' + tol + '% tolerance)');
      }
    }
  }

  const note = notes.join('; ');

  // Write only on an actual change. An unconditional upsert would rewrite every
  // row every morning, and a findings column that churns daily is one nobody reads.
  if (note !== String(t.notes || '') || newStatus !== t.status) {
    out.push({ json: { task_id: t.task_id, status: newStatus, notes: note } });
  }
}

return out;
